import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Diff.html","title":"Diff","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.36,"words":107},"filePathRelative":"Diff.md"}`),a={name:`Diff.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="diff" tabindex="-1"><a class="header-anchor" href="#diff"><span>Diff</span></a></h1><p><a href="./アルゴリズム.html">アルゴリズム</a>, <a href="./文字列マッチ.html">文字列マッチ</a></p><p>ここではアルゴリズムのdiffの話をする。 Longest Common Subsequence、略してLCSと呼ばれたりもする問題。</p><p><a href="./【書籍】IntroductionToAlgorithms.html">【書籍】IntroductionToAlgorithms</a>の15.4に基本的な話がある（Dynamic Programmingのサブセクション）。</p><h2 id="サブシークエンス" tabindex="-1"><a class="header-anchor" href="#サブシークエンス"><span>サブシークエンス</span></a></h2><p>歯抜けで取っていたものをサブシークエンスという。XとYの共通のサブシークエンスを探すのがLCS問題。間はあいて良い。</p><h2 id="theorem-15-1-optimal-substructure-of-an-lcs" tabindex="-1"><a class="header-anchor" href="#theorem-15-1-optimal-substructure-of-an-lcs"><span>Theorem 15.1, Optimal Substructure of an LCS</span></a></h2><p>DPを可能にする性質。</p><p><img src="/RandomThoughts/assets/0001-BWnLlfkn.png" alt="imgs/Diff/0001.png"></p><h2 id="xとyのlcsの長さとbテーブル" tabindex="-1"><a class="header-anchor" href="#xとyのlcsの長さとbテーブル"><span>XとYのLCSの長さとbテーブル</span></a></h2><p><img src="/RandomThoughts/assets/0002-BAUE0I4y.png" alt="imgs/Diff/0002.png"></p><h2 id="bテーブルからlcsの構築" tabindex="-1"><a class="header-anchor" href="#bテーブルからlcsの構築"><span>bテーブルからLCSの構築</span></a></h2><p><img src="/RandomThoughts/assets/0003-DFLwpk2v.png" alt="imgs/Diff/0003.png"></p><h2 id="myers-diff" tabindex="-1"><a class="header-anchor" href="#myers-diff"><span>Myers Diff</span></a></h2><p><a href="./アルゴリズム本.html">アルゴリズム本</a>とは異なるが、Myers Diffが現在良く使われるアルゴリズムになっている。</p><p>論文としては <a href="https://link.springer.com/article/10.1007/bf01840446" target="_blank" rel="noopener noreferrer">An O(ND) difference algorithm and its variations - Algorithmica - Springer Nature Link</a>。</p><p>Edit Graphを探す問題として最適な解を調べる。</p><p><img src="/RandomThoughts/assets/0004-DhEQKrWZ.png" alt="imgs/Diff/0004.png"></p><h3 id="逆向きの交差" tabindex="-1"><a class="header-anchor" href="#逆向きの交差"><span>逆向きの交差</span></a></h3><p><img src="/RandomThoughts/assets/0005-Fyo-cQNC.png" alt="imgs/Diff/0005.png"></p>`,20)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};